def background(grid):
    """The most frequent cell color."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def extend_diagonal_lines(grid, bg=None, min_len=2):
    """Each maximal diagonal run (length >= min_len) of one non-background color grows both ways through background cells until an edge or a non-background cell."""
    if bg is None: bg = background(grid)
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    for dr, dc in ((1, 1), (1, -1)):
        seen = set()
        for r in range(h):
            for c in range(w):
                if grid[r][c] == bg or (r, c) in seen: continue
                v = grid[r][c]
                # walk back to run start
                sr, sc = r, c
                while 0 <= sr-dr < h and 0 <= sc-dc < w and grid[sr-dr][sc-dc] == v:
                    sr -= dr; sc -= dc
                cells, rr, cc = [], sr, sc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == v:
                    cells.append((rr, cc)); seen.add((rr, cc)); rr += dr; cc += dc
                if len(cells) < min_len: continue
                for er, ec, dr2, dc2 in ((cells[0][0]-dr, cells[0][1]-dc, -dr, -dc), (cells[-1][0]+dr, cells[-1][1]+dc, dr, dc)):
                    while 0 <= er < h and 0 <= ec < w and grid[er][ec] == bg:
                        g[er][ec] = v; er += dr2; ec += dc2
    return g

